<?php/** * Service: Compliance Reports (Audit) — V1.0.5 *  * Generates downloadable PDF and CSV reports + scheduled email. * * @package MegaGovern * @since   1.0.5 */namespace MegaGovern;if ( ! defined( 'ABSPATH' ) ) {    exit;}/** * Class Reports * * Handles compliance report generation (PDF/CSV) and scheduled email delivery. */class Reports {    /**     * Constructor.     */    public function __construct() {        add_action( 'admin_post_megagovern_generate_report', array( $this, 'handle_report_generation' ) );    }    // ═══════════════════════════════════════    // DATA GENERATION    // ═══════════════════════════════════════    /**     * Generate report data.     *     * @param string $from Start date (Y-m-d).     * @param string $to   End date (Y-m-d).     * @return array     */    public static function generate_data( string $from = '', string $to = '' ): array {        $megagovern_stats = class_exists( '\MegaGovern\Registry' ) ? Registry::get_stats() : array();        $megagovern_verification_url = home_url( '/transparency' );        if ( class_exists( '\MegaGovern\Verification' ) && method_exists( '\MegaGovern\Verification', 'get_transparency_url' ) ) {            $megagovern_verification_url = \MegaGovern\Verification::get_transparency_url();        }        return array(            'site_name'    => get_bloginfo( 'name' ),            'site_url'     => get_home_url(),            'generated_at' => current_time( 'Y-m-d H:i:s' ),            'date_range'   => array(                'from' => $from ?: __( 'All time', 'megagovern' ),                'to'   => $to ?: __( 'Present', 'megagovern' ),            ),            'stats'        => $megagovern_stats,            'verification' => $megagovern_verification_url,            'aitxt'        => home_url( '/ai.txt' ),        );    }    // ═══════════════════════════════════════    // CSV GENERATION    // ═══════════════════════════════════════    /**     * Generate CSV content with Media & C2PA Governance stats.     *     * @param array $data Report data.     * @return string CSV content.     */    public static function generate_csv( array $data ): string {        // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fopen        $megagovern_output = fopen( 'php://temp', 'r+' );        // Header        fputcsv( $megagovern_output, array( 'MegaGovern Compliance & Audit Report' ) );        fputcsv( $megagovern_output, array( 'Site: ' . $data['site_name'] ) );        fputcsv( $megagovern_output, array( 'Generated: ' . $data['generated_at'] ) );        fputcsv( $megagovern_output, array() );        // Content Stats        fputcsv( $megagovern_output, array( __( 'Content Declarations Summary', 'megagovern' ) ) );        fputcsv( $megagovern_output, array( __( 'Total Declared Posts', 'megagovern' ), isset( $data['stats']['total'] ) ? (int) $data['stats']['total'] : 0 ) );        fputcsv( $megagovern_output, array( __( 'Human Made', 'megagovern' ), isset( $data['stats']['human'] ) ? (int) $data['stats']['human'] : 0 ) );        fputcsv( $megagovern_output, array( __( 'AI Modified', 'megagovern' ), isset( $data['stats']['ai_assisted'] ) ? (int) $data['stats']['ai_assisted'] : 0 ) );        fputcsv( $megagovern_output, array( __( 'Fully AI-Generated', 'megagovern' ), isset( $data['stats']['ai_generated'] ) ? (int) $data['stats']['ai_generated'] : 0 ) );        fputcsv( $megagovern_output, array( __( 'Synthetic / Deepfake', 'megagovern' ), isset( $data['stats']['deepfake'] ) ? (int) $data['stats']['deepfake'] : 0 ) );        fputcsv( $megagovern_output, array() );        // Media & C2PA Stats        $megagovern_media_stats = self::get_media_governance_stats();        fputcsv( $megagovern_output, array( __( 'Media & Provenance Summary (C2PA / IPTC)', 'megagovern' ) ) );        fputcsv( $megagovern_output, array( __( 'Total Audited Media Items', 'megagovern' ), $megagovern_media_stats['total_media'] ) );        fputcsv( $megagovern_output, array( __( 'Human Media', 'megagovern' ), $megagovern_media_stats['media_human'] ) );        fputcsv( $megagovern_output, array( __( 'AI Generated Images', 'megagovern' ), $megagovern_media_stats['media_ai_generated'] ) );        fputcsv( $megagovern_output, array( __( 'AI Assisted / Modified Images', 'megagovern' ), $megagovern_media_stats['media_ai_assisted'] ) );        fputcsv( $megagovern_output, array( __( 'Synthetic / Deepfake Media', 'megagovern' ), $megagovern_media_stats['media_deepfake'] ) );        fputcsv( $megagovern_output, array( __( 'Valid C2PA Manifests Found', 'megagovern' ), $megagovern_media_stats['c2pa_detected'] ) );        fputcsv( $megagovern_output, array( __( 'IPTC Headers Embedded', 'megagovern' ), $megagovern_media_stats['iptc_synced'] ) );        fputcsv( $megagovern_output, array() );        // Public URLs        fputcsv( $megagovern_output, array( __( 'Public Transparency URLs', 'megagovern' ) ) );        fputcsv( $megagovern_output, array( __( 'Verification Page', 'megagovern' ), $data['verification'] ) );        fputcsv( $megagovern_output, array( __( 'AI.txt File', 'megagovern' ), $data['aitxt'] ) );        fputcsv( $megagovern_output, array() );        // Legal Disclaimer        fputcsv( $megagovern_output, array( str_repeat( '=', 60 ) ) );        fputcsv( $megagovern_output, array( __( 'IMPORTANT LEGAL DISCLAIMER', 'megagovern' ) ) );        fputcsv( $megagovern_output, array( str_repeat( '=', 60 ) ) );        fputcsv( $megagovern_output, array( __( 'This report is generated by the MegaGovern plugin for transparency and documentation purposes only.', 'megagovern' ) ) );        fputcsv( $megagovern_output, array( __( 'It does NOT constitute legal advice, legal compliance certification, or a guarantee of regulatory compliance.', 'megagovern' ) ) );        fputcsv( $megagovern_output, array( __( 'Legal compliance depends on your jurisdiction, your content, and your legal counsel.', 'megagovern' ) ) );        fputcsv( $megagovern_output, array( __( 'Meganova Agency makes no representations or warranties regarding the completeness or accuracy of this data for legal purposes.', 'megagovern' ) ) );        fputcsv( $megagovern_output, array( __( 'Users should consult qualified legal counsel for compliance determinations specific to their situation.', 'megagovern' ) ) );        rewind( $megagovern_output );        $megagovern_csv = stream_get_contents( $megagovern_output );        // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fclose        fclose( $megagovern_output );        return $megagovern_csv;    }    // ═══════════════════════════════════════    // PDF GENERATION    // ═══════════════════════════════════════    /**     * Generate PDF using Dompdf.     *     * @param string $from Start date.     * @param string $to   End date.     */    public static function generate_pdf( string $from = '', string $to = '' ): void {        $megagovern_data = self::generate_data( $from, $to );        ob_start();        $megagovern_report_tpl = MEGAGOVERN_PATH . 'templates/public/report-pdf.php';        if ( file_exists( $megagovern_report_tpl ) ) {            include $megagovern_report_tpl;        }        $megagovern_html = ob_get_clean();        // ─── Check if Dompdf exists ───        $megagovern_dompdf_path = MEGAGOVERN_PATH . 'vendor/dompdf/autoload.php';        if ( file_exists( $megagovern_dompdf_path ) ) {            require_once $megagovern_dompdf_path;            $megagovern_dompdf = new \Dompdf\Dompdf();            $megagovern_dompdf->loadHtml( $megagovern_html );            $megagovern_dompdf->setPaper( 'A4', 'portrait' );            $megagovern_dompdf->render();            $megagovern_dompdf->stream(                'megagovern-report-' . gmdate( 'Y-m-d' ) . '.pdf',                array( 'Attachment' => true )            );            if ( class_exists( '\MegaGovern\Governance' ) ) {                Governance::log_action(                    Governance::ACTION_AUDIT,                    0,                    'system',                    get_current_user_id(),                    array( 'note' => __( 'PDF report generated.', 'megagovern' ) )                );            }            exit;        }        // ─── Fallback: HTML output ───        header( 'Content-Type: text/html; charset=utf-8' );        header( 'Content-Disposition: attachment; filename="megagovern-report-' . gmdate( 'Y-m-d' ) . '.html"' );        echo wp_kses_post( $megagovern_html );        exit;    }    // ═══════════════════════════════════════    // REQUEST HANDLER    // ═══════════════════════════════════════    /**     * Handle report download request.     */    public function handle_report_generation(): void {        if ( ! current_user_can( 'manage_options' ) && ! current_user_can( 'megagovern_manage_compliance' ) ) {            wp_die( esc_html__( 'You do not have sufficient permissions.', 'megagovern' ) );        }        check_admin_referer( 'megagovern_generate_report' );        $megagovern_from   = isset( $_GET['from'] ) ? sanitize_text_field( wp_unslash( $_GET['from'] ) ) : '';        $megagovern_to     = isset( $_GET['to'] ) ? sanitize_text_field( wp_unslash( $_GET['to'] ) ) : '';        $megagovern_format = isset( $_GET['format'] ) ? sanitize_text_field( wp_unslash( $_GET['format'] ) ) : 'csv';        if ( 'pdf' === $megagovern_format ) {            $megagovern_is_pro = false;            if ( class_exists( '\MegaGovern\License' ) ) {                $megagovern_is_pro = License::is_pro() || License::is_agency();            }            if ( ! $megagovern_is_pro ) {                wp_die( esc_html__( 'PDF reports require a Pro or Agency license.', 'megagovern' ) );            }            self::generate_pdf( $megagovern_from, $megagovern_to );            return;        }        // CSV        $megagovern_data     = self::generate_data( $megagovern_from, $megagovern_to );        $megagovern_content  = self::generate_csv( $megagovern_data );        $megagovern_filename = 'megagovern-report-' . gmdate( 'Y-m-d' ) . '.csv';        header( 'Content-Type: text/csv; charset=utf-8' );        header( 'Content-Disposition: attachment; filename="' . esc_attr( $megagovern_filename ) . '"' );        header( 'Content-Length: ' . strlen( $megagovern_content ) );        echo wp_kses_post( $megagovern_content );        exit;    }    // ═══════════════════════════════════════    // SCHEDULED REPORT    // ═══════════════════════════════════════    /**     * Send scheduled report via email.     */    public static function send_scheduled_report(): void {        $megagovern_schedule = get_option( 'megagovern_report_schedule', 'none' );        $megagovern_email    = get_option( 'megagovern_report_email', '' );        if ( 'none' === $megagovern_schedule || empty( $megagovern_email ) || ! is_email( $megagovern_email ) ) {            return;        }        // Lock to prevent double send on overlapping cron        $megagovern_lock_key = 'megagovern_report_sending_lock';        if ( get_transient( $megagovern_lock_key ) ) {            return;        }        set_transient( $megagovern_lock_key, 1, 5 * MINUTE_IN_SECONDS );        // Check interval        $megagovern_last_sent = (int) get_option( 'megagovern_report_last_sent', 0 );        $megagovern_now        = time();        $megagovern_interval  = array(            'weekly'    => WEEK_IN_SECONDS,            'monthly'   => 30 * DAY_IN_SECONDS,            'quarterly' => 90 * DAY_IN_SECONDS,        );        if ( isset( $megagovern_interval[ $megagovern_schedule ] ) && ( $megagovern_now - $megagovern_last_sent ) < $megagovern_interval[ $megagovern_schedule ] ) {            delete_transient( $megagovern_lock_key );            return;        }        $megagovern_data     = self::generate_data();        $megagovern_csv      = self::generate_csv( $megagovern_data );        $megagovern_stats    = $megagovern_data['stats'];        $megagovern_total    = isset( $megagovern_stats['total'] ) ? (int) $megagovern_stats['total'] : 0;        $megagovern_human    = isset( $megagovern_stats['human'] ) ? (int) $megagovern_stats['human'] : 0;        $megagovern_assist   = isset( $megagovern_stats['ai_assisted'] ) ? (int) $megagovern_stats['ai_assisted'] : 0;        $megagovern_gen      = isset( $megagovern_stats['ai_generated'] ) ? (int) $megagovern_stats['ai_generated'] : 0;        $megagovern_deepfake = isset( $megagovern_stats['deepfake'] ) ? (int) $megagovern_stats['deepfake'] : 0;        $megagovern_undecl   = class_exists( '\MegaGovern\Registry' ) ? Registry::count_undeclared() : 0;        $megagovern_all      = $megagovern_total + $megagovern_undecl;        $megagovern_coverage = $megagovern_all > 0 ? (int) round( ( $megagovern_total / $megagovern_all ) * 100 ) : 100;        // Temp file using wp_tempnam — safe, auto-cleaned        $megagovern_temp_file = wp_tempnam( 'megagovern-report-' . gmdate( 'Y-m-d' ) . '.csv' );        if ( ! $megagovern_temp_file ) {            delete_transient( $megagovern_lock_key );                        // Use error_log only when WP_DEBUG is enabled            if ( defined( 'WP_DEBUG' ) && WP_DEBUG ) {                // phpcs:ignore WordPress.PHP.DevelopmentFunctions.error_log_error_log                error_log( '[MegaGovern] Failed to create temp file for scheduled report.' );            }            return;        }        // Move to .csv extension using WP_Filesystem        $megagovern_filepath = $megagovern_temp_file . '.csv';                global $wp_filesystem;        require_once ABSPATH . 'wp-admin/includes/file.php';        WP_Filesystem();                if ( $wp_filesystem ) {            $megagovern_written = $wp_filesystem->put_contents( $megagovern_filepath, $megagovern_csv );            if ( ! $megagovern_written ) {                $wp_filesystem->delete( $megagovern_filepath );                $wp_filesystem->delete( $megagovern_temp_file );                delete_transient( $megagovern_lock_key );                if ( defined( 'WP_DEBUG' ) && WP_DEBUG ) {                    // phpcs:ignore WordPress.PHP.DevelopmentFunctions.error_log_error_log                    error_log( '[MegaGovern] Failed to write CSV for scheduled report.' );                }                return;            }        } else {            // Fallback to file_put_contents            $megagovern_written = file_put_contents( $megagovern_filepath, $megagovern_csv );            if ( false === $megagovern_written ) {                wp_delete_file( $megagovern_filepath );                wp_delete_file( $megagovern_temp_file );                delete_transient( $megagovern_lock_key );                if ( defined( 'WP_DEBUG' ) && WP_DEBUG ) {                    // phpcs:ignore WordPress.PHP.DevelopmentFunctions.error_log_error_log                    error_log( '[MegaGovern] Failed to write CSV for scheduled report.' );                }                return;            }        }        // Sender config        $megagovern_site_name   = get_bloginfo( 'name' );        $megagovern_admin_email = get_bloginfo( 'admin_email' );        $megagovern_from_name   = $megagovern_site_name . ' — ' . __( 'MegaGovern Transparency', 'megagovern' );        $megagovern_filter_from        = function() use ( $megagovern_admin_email ) {            return $megagovern_admin_email;        };        $megagovern_filter_from_name  = function() use ( $megagovern_from_name ) {            return $megagovern_from_name;        };        add_filter( 'wp_mail_from', $megagovern_filter_from );        add_filter( 'wp_mail_from_name', $megagovern_filter_from_name );        $megagovern_subject = sprintf(            /* translators: %1$s: site name, %2$d: coverage percentage, %3$s: date */            __( '[%1$s] Transparency Report — %2$d%% Coverage — %3$s', 'megagovern' ),            $megagovern_site_name,            $megagovern_coverage,            date_i18n( get_option( 'date_format' ) )        );        $megagovern_body  = '<!DOCTYPE html><html><head><meta charset="utf-8">';        $megagovern_body .= '<style>body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;color:#1d2327;line-height:1.6;max-width:600px;margin:0 auto;padding:20px}h2{color:#2271b1;margin-top:0}.stats-table{width:100%;border-collapse:collapse;margin:16px 0}.stats-table td{padding:8px 12px;border-bottom:1px solid #e5e5e5}.stats-table td:last-child{text-align:right;font-weight:600}.highlight{background:#f0f6fc;border-radius:4px;padding:12px;margin:16px 0}.footer{font-size:11px;color:#646970;margin-top:24px;border-top:1px solid #e5e5e5;padding-top:12px}.disclaimer{font-size:11px;color:#dba617;font-style:italic;margin-top:8px}</style></head><body>';        $megagovern_body .= '<h2>' . esc_html( $megagovern_site_name ) . '</h2>';        $megagovern_body .= '<p>' . esc_html__( 'Your scheduled transparency report is attached.', 'megagovern' ) . '</p>';        $megagovern_body .= '<div class="highlight">';        $megagovern_body .= '<strong>' . esc_html__( 'Coverage:', 'megagovern' ) . '</strong> ' . esc_html( (string) $megagovern_coverage ) . '%<br>';        $megagovern_body .= '<strong>' . esc_html__( 'Declared:', 'megagovern' ) . '</strong> ' . esc_html( (string) $megagovern_total ) . ' / ' . esc_html( (string) $megagovern_all ) . ' ' . esc_html__( 'published items', 'megagovern' );        $megagovern_body .= '</div>';        $megagovern_body .= '<table class="stats-table">';        $megagovern_body .= '<tr><td>' . esc_html__( 'Human Made', 'megagovern' ) . '</td><td>' . esc_html( (string) $megagovern_human ) . '</td></tr>';        $megagovern_body .= '<tr><td>' . esc_html__( 'AI Modified', 'megagovern' ) . '</td><td>' . esc_html( (string) $megagovern_assist ) . '</td></tr>';        $megagovern_body .= '<tr><td>' . esc_html__( 'Fully AI-Generated', 'megagovern' ) . '</td><td>' . esc_html( (string) $megagovern_gen ) . '</td></tr>';        $megagovern_body .= '<tr><td>' . esc_html__( 'Synthetic / Deepfake', 'megagovern' ) . '</td><td>' . esc_html( (string) $megagovern_deepfake ) . '</td></tr>';        $megagovern_body .= '<tr><td>' . esc_html__( 'Undeclared', 'megagovern' ) . '</td><td>' . esc_html( (string) $megagovern_undecl ) . '</td></tr>';        $megagovern_body .= '</table>';        $megagovern_body .= '<p>';        $megagovern_body .= '<a href="' . esc_url( $megagovern_data['verification'] ) . '">' . esc_html__( 'View Verification Page', 'megagovern' ) . '</a> &nbsp;|&nbsp; ';        $megagovern_body .= '<a href="' . esc_url( $megagovern_data['aitxt'] ) . '">' . esc_html__( 'View AI.txt', 'megagovern' ) . '</a>';        $megagovern_body .= '</p>';        $megagovern_body .= '<div class="footer">';        $megagovern_body .= '<p class="disclaimer"><strong>' . esc_html__( 'DISCLAIMER:', 'megagovern' ) . '</strong> ' . esc_html__( 'This report is generated for transparency and documentation purposes only. It does not constitute legal compliance certification or legal advice. Consult qualified legal counsel for compliance determinations specific to your jurisdiction.', 'megagovern' ) . '</p>';        $megagovern_body .= '<p>' . esc_html( sprintf(            /* translators: %1$s: recipient email, %2$s: schedule frequency */ __( 'This report was automatically generated by MegaGovern — AI Content Governance & Transparency Platform. Sent to %1$s on a %2$s schedule.', 'megagovern' ),            $megagovern_email,            $megagovern_schedule        ) ) . '</p>';        $megagovern_body .= '</div></body></html>';        $megagovern_headers = array(            'Content-Type: text/html; charset=UTF-8',            'Reply-To: ' . $megagovern_admin_email,        );        $megagovern_sent = wp_mail( $megagovern_email, $megagovern_subject, $megagovern_body, $megagovern_headers, array( $megagovern_filepath ) );        // Clean up filters        remove_filter( 'wp_mail_from', $megagovern_filter_from );        remove_filter( 'wp_mail_from_name', $megagovern_filter_from_name );        // Clean up files using wp_delete_file        if ( $wp_filesystem ) {            if ( $wp_filesystem->exists( $megagovern_filepath ) ) {                $wp_filesystem->delete( $megagovern_filepath );            }            if ( $wp_filesystem->exists( $megagovern_temp_file ) ) {                $wp_filesystem->delete( $megagovern_temp_file );            }        } else {            wp_delete_file( $megagovern_filepath );            wp_delete_file( $megagovern_temp_file );        }        delete_transient( $megagovern_lock_key );        if ( $megagovern_sent ) {            update_option( 'megagovern_report_last_sent', $megagovern_now );            if ( class_exists( '\MegaGovern\Governance' ) ) {                Governance::log_action(                    Governance::ACTION_AUDIT,                    0,                    'system',                    0,                    array( 'note' => sprintf(                        /* translators: %s: recipient email address */ __( 'Scheduled report emailed to %s.', 'megagovern' ),                        $megagovern_email                    ) )                );            }        } else {            if ( defined( 'WP_DEBUG' ) && WP_DEBUG ) {                // phpcs:ignore WordPress.PHP.DevelopmentFunctions.error_log_error_log                error_log( sprintf( '[MegaGovern] Scheduled report email failed to %s', $megagovern_email ) );            }        }    }    // ═══════════════════════════════════════    // MEDIA STATS    // ═══════════════════════════════════════    /**     * Get media governance statistics.     *     * @return array     */    private static function get_media_governance_stats(): array {        $cache_key = 'megagovern_media_governance_stats';        $cached    = wp_cache_get( $cache_key, 'megagovern' );        if ( false !== $cached && is_array( $cached ) ) {            return $cached;        }        global $wpdb;        // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching        $megagovern_total_media = (int) $wpdb->get_var(            "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type = 'attachment'"        );        // Helper to count only attachments        $megagovern_count_by_value = function( string $meta_value ) use ( $wpdb ): int {            // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching            return (int) $wpdb->get_var( $wpdb->prepare(                "SELECT COUNT(*) FROM {$wpdb->postmeta} pm                 INNER JOIN {$wpdb->posts} p ON p.ID = pm.post_id                 WHERE p.post_type = 'attachment'                 AND pm.meta_key = %s                 AND pm.meta_value = %s",                '_megagovern_declaration',                $meta_value            ) );        };        $megagovern_media_human      = $megagovern_count_by_value( 'human' );        $megagovern_media_ai_gen    = $megagovern_count_by_value( 'ai_generated' );        $megagovern_media_ai_assist = $megagovern_count_by_value( 'ai_assisted' );        $megagovern_media_deepfake  = $megagovern_count_by_value( 'deepfake' );        // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching        $megagovern_iptc_synced = (int) $wpdb->get_var( $wpdb->prepare(            "SELECT COUNT(*) FROM {$wpdb->postmeta} pm             INNER JOIN {$wpdb->posts} p ON p.ID = pm.post_id             WHERE p.post_type = 'attachment'             AND pm.meta_key = %s AND pm.meta_value = %s",            '_megagovern_iptc_synced',            '1'        ) );        $megagovern_c2pa_like = '%' . $wpdb->esc_like( '"c2pa_manifest_found":true' ) . '%';        // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching        $megagovern_c2pa_detected = (int) $wpdb->get_var( $wpdb->prepare(            "SELECT COUNT(*) FROM {$wpdb->postmeta} pm             INNER JOIN {$wpdb->posts} p ON p.ID = pm.post_id             WHERE p.post_type = 'attachment'             AND pm.meta_key = %s AND pm.meta_value LIKE %s",            '_megagovern_upload_provenance',            $megagovern_c2pa_like        ) );        $megagovern_stats = array(            'total_media'        => $megagovern_total_media,            'media_human'        => $megagovern_media_human,            'media_ai_generated' => $megagovern_media_ai_gen,            'media_ai_assisted'  => $megagovern_media_ai_assist,            'media_deepfake'     => $megagovern_media_deepfake,            'c2pa_detected'      => $megagovern_c2pa_detected,            'iptc_synced'        => $megagovern_iptc_synced,        );        wp_cache_set( $cache_key, $megagovern_stats, 'megagovern', HOUR_IN_SECONDS );        return $megagovern_stats;    }}